pygments.cmdline.main_inner:
def main_inner(parser, argns):
    if argns.help:
        parser.print_help()
        return 0
    if argns.V:
        print(f'Pygments version {__version__}, (c) 2006-present by Georg Brandl, Matthäus Chajdas and contributors.')
        return 0

    def is_only_option(opt):
        return not any((v for (k, v) in vars(argns).items() if k != opt))
    if argns.L is not None:
        arg_set = set()
        for (k, v) in vars(argns).items():
            if v:
                arg_set.add(k)
        arg_set.discard('L')
        arg_set.discard('json')
        if arg_set:
            parser.print_help(sys.stderr)
            return 2
        if not argns.json:
            main(['', '-V'])
        allowed_types = {'lexer', 'formatter', 'filter', 'style'}
        largs = [arg.rstrip('s') for arg in argns.L]
        if any((arg not in allowed_types for arg in largs)):
            parser.print_help(sys.stderr)
            return 0
        if not largs:
            largs = allowed_types
        if not argns.json:
            for arg in largs:
                _print_list(arg)
        else:
            _print_list_as_json(largs)
        return 0
    if argns.H:
        if not is_only_option('H'):
            parser.print_help(sys.stderr)
            return 2
        (what, name) = argns.H
        if what not in ('lexer', 'formatter', 'filter'):
            parser.print_help(sys.stderr)
            return 2
        return _print_help(what, name)
    parsed_opts = _parse_options((argns.O or []))
    for p_opt in (argns.P or []):
        try:
            (name, value) = p_opt.split('=', 1)
        except ValueError:
            parsed_opts[p_opt] = True
        else:
            parsed_opts[name] = value
    inencoding = parsed_opts.get('inencoding', parsed_opts.get('encoding'))
    outencoding = parsed_opts.get('outencoding', parsed_opts.get('encoding'))
    if argns.N:
        lexer = find_lexer_class_for_filename(argns.N)
        if lexer is None:
            lexer = TextLexer
        print(lexer.aliases[0])
        return 0
    if argns.C:
        inp = sys.stdin.buffer.read()
        try:
            lexer = guess_lexer(inp, inencoding=inencoding)
        except ClassNotFound:
            lexer = TextLexer
        print(lexer.aliases[0])
        return 0
    S_opt = argns.S
    a_opt = argns.a
    if S_opt is not None:
        f_opt = argns.f
        if not f_opt:
            parser.print_help(sys.stderr)
            return 2
        if (argns.l or argns.INPUTFILE):
            parser.print_help(sys.stderr)
            return 2
        try:
            parsed_opts['style'] = S_opt
            fmter = get_formatter_by_name(f_opt, **parsed_opts)
        except ClassNotFound as err:
            print(err, file=sys.stderr)
            return 1
        print(fmter.get_style_defs((a_opt or '')))
        return 0
    if argns.a is not None:
        parser.print_help(sys.stderr)
        return 2
    F_opts = _parse_filters((argns.F or []))
    allow_custom_lexer_formatter = bool(argns.x)
    lexer = None
    lexername = argns.l
    if lexername:
        if (allow_custom_lexer_formatter and '.py' in lexername):
            try:
                filename = None
                name = None
                if ':' in lexername:
                    (filename, name) = lexername.rsplit(':', 1)
                    if '.py' in name:
                        name = None
                if (filename and name):
                    lexer = load_lexer_from_file(filename, name, **parsed_opts)
                else:
                    lexer = load_lexer_from_file(lexername, **parsed_opts)
            except ClassNotFound as err:
                print('Error:', err, file=sys.stderr)
                return 1
        else:
            try:
                lexer = get_lexer_by_name(lexername, **parsed_opts)
            except (OptionError, ClassNotFound) as err:
                print('Error:', err, file=sys.stderr)
                return 1
    code = None
    if argns.INPUTFILE:
        if argns.s:
            print('Error: -s option not usable when input file specified', file=sys.stderr)
            return 2
        infn = argns.INPUTFILE
        try:
            with open(infn, 'rb') as infp:
                code = infp.read()
        except Exception as err:
            print('Error: cannot read infile:', err, file=sys.stderr)
            return 1
        if not inencoding:
            (code, inencoding) = guess_decode(code)
        if not lexer:
            try:
                lexer = get_lexer_for_filename(infn, code, **parsed_opts)
            except ClassNotFound as err:
                if argns.g:
                    try:
                        lexer = guess_lexer(code, **parsed_opts)
                    except ClassNotFound:
                        lexer = TextLexer(**parsed_opts)
                else:
                    print('Error:', err, file=sys.stderr)
                    return 1
            except OptionError as err:
                print('Error:', err, file=sys.stderr)
                return 1
    elif not argns.s:
        code = sys.stdin.buffer.read()
        if not inencoding:
            (code, inencoding) = guess_decode_from_terminal(code, sys.stdin)
        if not lexer:
            try:
                lexer = guess_lexer(code, **parsed_opts)
            except ClassNotFound:
                lexer = TextLexer(**parsed_opts)
    elif not lexer:
        print('Error: when using -s a lexer has to be selected with -l', file=sys.stderr)
        return 2
    for (fname, fopts) in F_opts:
        try:
            lexer.add_filter(fname, **fopts)
        except ClassNotFound as err:
            print('Error:', err, file=sys.stderr)
            return 1
    outfn = argns.o
    fmter = argns.f
    if fmter:
        if (allow_custom_lexer_formatter and '.py' in fmter):
            try:
                filename = None
                name = None
                if ':' in fmter:
                    (filename, name) = fmter.rsplit(':', 1)
                    if '.py' in name:
                        name = None
                if (filename and name):
                    fmter = load_formatter_from_file(filename, name, **parsed_opts)
                else:
                    fmter = load_formatter_from_file(fmter, **parsed_opts)
            except ClassNotFound as err:
                print('Error:', err, file=sys.stderr)
                return 1
        else:
            try:
                fmter = get_formatter_by_name(fmter, **parsed_opts)
            except (OptionError, ClassNotFound) as err:
                print('Error:', err, file=sys.stderr)
                return 1
    if outfn:
        if not fmter:
            try:
                fmter = get_formatter_for_filename(outfn, **parsed_opts)
            except (OptionError, ClassNotFound) as err:
                print('Error:', err, file=sys.stderr)
                return 1
        try:
            outfile = open(outfn, 'wb')
        except Exception as err:
            print('Error: cannot open outfile:', err, file=sys.stderr)
            return 1
    else:
        if not fmter:
            if os.environ.get('COLORTERM', '') in ('truecolor', '24bit'):
                fmter = TerminalTrueColorFormatter(**parsed_opts)
            elif '256' in os.environ.get('TERM', ''):
                fmter = Terminal256Formatter(**parsed_opts)
            else:
                fmter = TerminalFormatter(**parsed_opts)
        outfile = sys.stdout.buffer
    if not outencoding:
        if outfn:
            fmter.encoding = inencoding
        else:
            fmter.encoding = terminal_encoding(sys.stdout)
    if (not outfn and sys.platform in ('win32', 'cygwin') and fmter.name in ('Terminal', 'Terminal256')):
        outfile = UnclosingTextIOWrapper(outfile, encoding=fmter.encoding)
        fmter.encoding = None
        try:
            import colorama.initialise
        except ImportError:
            pass
        else:
            outfile = colorama.initialise.wrap_stream(outfile, convert=None, strip=None, autoreset=False, wrap=True)
    escapeinside = parsed_opts.get('escapeinside', '')
    if (len(escapeinside) == 2 and isinstance(fmter, LatexFormatter)):
        left = escapeinside[0]
        right = escapeinside[1]
        lexer = LatexEmbeddedLexer(left, right, lexer)
    if not argns.s:
        try:
            highlight(code, lexer, fmter, outfile)
        finally:
            if outfn:
                outfile.close()
        return 0
    else:
        try:
            try:
                while 1:
                    line = sys.stdin.buffer.readline()
                    if not line:
                        break
                    if not inencoding:
                        line = guess_decode_from_terminal(line, sys.stdin)[0]
                    highlight(line, lexer, fmter, outfile)
                    if hasattr(outfile, 'flush'):
                        outfile.flush()
                return 0
            except KeyboardInterrupt:
                return 0
        finally:
            if outfn:
                outfile.close()

pygments.util.format_lines:
def format_lines(var_name, seq, raw=False, indent_level=0):
    """Formats a sequence of strings for output."""
    lines = []
    base_indent = ' ' * indent_level * 4
    inner_indent = ' ' * (indent_level + 1) * 4
    lines.append(base_indent + var_name + ' = (')
    if raw:
        for i in seq:
            lines.append(inner_indent + i + ',')
    else:
        for i in seq:
            r = repr(i + '"')
            lines.append(inner_indent + r[:-2] + r[-1] + ',')
    lines.append(base_indent + ')')
    return '\n'.join(lines)

pygments.lexers.css._starts_block:
def _starts_block(token, state):

    def callback(lexer, match, ctx):
        yield (match.start(), token, match.group(0))
        if hasattr(ctx, 'last_indentation'):
            ctx.block_indentation = ctx.last_indentation
        else:
            ctx.block_indentation = ''
        ctx.block_state = state
        ctx.pos = match.end()
    return callback

pygments.lexers._lua_builtins.module_cal:
def module_callbacks():

    def is_in_coroutine_module(name):
        return name.startswith('coroutine.')

    def is_in_modules_module(name):
        if (name in ['require', 'module'] or name.startswith('package')):
            return True
        else:
            return False

    def is_in_string_module(name):
        return name.startswith('string.')

    def is_in_table_module(name):
        return name.startswith('table.')

    def is_in_math_module(name):
        return name.startswith('math')

    def is_in_io_module(name):
        return name.startswith('io.')

    def is_in_os_module(name):
        return name.startswith('os.')

    def is_in_debug_module(name):
        return name.startswith('debug.')
    return {'coroutine': is_in_coroutine_module, 'modules': is_in_modules_module, 'string': is_in_string_module, 'table': is_in_table_module, 'math': is_in_math_module, 'io': is_in_io_module, 'os': is_in_os_module, 'debug': is_in_debug_module}

pygments.lexers.__init__.get_lexer_by_na:
def get_lexer_by_name(_alias, **options):
    """
    Return an instance of a `Lexer` subclass that has `alias` in its
    aliases list. The lexer is given the `options` at its
    instantiation.

    Will raise :exc:`pygments.util.ClassNotFound` if no lexer with that alias is
    found.
    """
    if not _alias:
        raise ClassNotFound(f'no lexer for alias {_alias!r} found')
    for (module_name, name, aliases, _, _) in LEXERS.values():
        if _alias.lower() in aliases:
            if name not in _lexer_cache:
                _load_lexers(module_name)
            return _lexer_cache[name](**options)
    for cls in find_plugin_lexers():
        if _alias.lower() in cls.aliases:
            return cls(**options)
    raise ClassNotFound(f'no lexer for alias {_alias!r} found')

pygments.lexers.erlang.gen_elixir_sigstr:
def gen_elixir_sigstr_rules(term, term_class, token, interpol=True):
    if interpol:
        return [(f'[^#{term_class}\\\\]+', token), include('escapes'), ('\\\\.', token), (f'{term}[a-zA-Z]*', token, '#pop'), include('interpol')]
    else:
        return [(f'[^{term_class}\\\\]+', token), ('\\\\.', token), (f'{term}[a-zA-Z]*', token, '#pop')]

pygments.lexers._mysql_builtins.parse_le:
def parse_lex_optimizer_hints(f):
    """Parse optimizer hints in lex.h."""
    results = set()
    for m in re.finditer('{SYM_H\\("(?P<keyword>[a-z0-9_]+)",', f, flags=re.I):
        results.add(m.group('keyword').lower())
    if not results:
        raise ValueError('No optimizer hints found')
    return results
